"""Shared Ballast research presentation. Pure rendering, no simulations."""
CSS='''
:root{color-scheme:dark;--bg:#07090d;--card:#0d1117;--line:#1e2632;--ink:#dce3ec;--muted:#98a6b8;--teal:#4fe3c1;--amber:#f2b24c}
*{box-sizing:border-box}body{margin:0;background:var(--bg);background-image:radial-gradient(#18202b 1px,transparent 1px);background-size:24px 24px;color:var(--ink);font:15px/1.7 'IBM Plex Sans',system-ui,sans-serif}main{max-width:1160px;margin:auto;padding:36px 32px 70px}h1,h2,h3{font-family:'Space Grotesk',system-ui,sans-serif;line-height:1.3;letter-spacing:-.02em}h1{font-size:38px;margin:12px 0 22px}h2{font-size:25px;margin:46px 0 18px;padding-top:22px;border-top:1px solid var(--line);scroll-margin-top:20px}p,li{max-width:90ch;color:#b7c3d1}a{color:var(--teal)}code{font:12px ui-monospace,monospace;overflow-wrap:anywhere;color:#b8c7db}.eyebrow{font:11px ui-monospace,monospace;letter-spacing:.15em;text-transform:uppercase;color:var(--teal)}.callout,.archive{background:#14241f;border:1px solid #2e4d41;border-radius:18px;padding:22px}.archive{background:#241f13;border-color:#5b4525;color:#f2d8a1}.archive strong{display:block;color:var(--amber);font-size:17px;margin-bottom:6px}figure{margin:24px 0;padding:20px;background:var(--card);border:1px solid var(--line);border-radius:20px;overflow:auto}img{display:block;width:100%;height:auto}figcaption{font-size:13px;color:var(--muted);padding:16px 6px 0;max-width:90ch}table{border-collapse:collapse;width:100%;font-size:13px;background:var(--card)}th,td{border-bottom:1px solid var(--line);text-align:left;padding:14px 12px;vertical-align:top}th{color:var(--muted);font:11px ui-monospace,monospace;text-transform:uppercase}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:16px;margin:20px 0}nav{display:flex;gap:8px;flex-wrap:wrap;margin:22px 0}nav a{border:1px solid var(--line);border-radius:999px;padding:8px 14px;text-decoration:none;font-size:12px;background:var(--card)}.research-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:24px 0}.research-cards>div{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:20px}.research-cards b{display:block;font-size:27px;color:var(--ink)}.research-cards span{font-size:12px;color:var(--muted)}.mobile-note{display:none}
@media(max-width:600px){main{padding:24px 16px 50px}h1{font-size:29px}h2{font-size:23px}.research-cards{grid-template-columns:1fr}.research-cards>div{padding:16px}figure{padding:12px}figure img{width:620px;max-width:none}figcaption{width:100%;min-width:0;font-size:13px}.mobile-note{display:block;font-size:12px;color:var(--muted)}table{min-width:560px}.archive{padding:18px}nav a{font-size:11px;padding:7px 11px}}
'''


def apply_matplotlib(plt):
    plt.rcParams.update({'font.size':11,'axes.spines.top':False,'axes.spines.right':False,'figure.facecolor':'#0d1117','axes.facecolor':'#0d1117','text.color':'#dce3ec','axes.labelcolor':'#c1cddd','xtick.color':'#98a6b8','ytick.color':'#98a6b8','axes.edgecolor':'#344050','grid.color':'#344050','svg.fonttype':'none','savefig.bbox':'tight','font.family':'DejaVu Sans'})
